<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import M9Sidebar from '../components/M9Sidebar.vue'
import MovieDetailView from './MovieDetailView.vue'
import MyMoviesView from './MyMoviesView.vue'
import {movieArtwork} from '../services/movieArtwork'
const route=useRoute(),router=useRouter(),expanded=ref(localStorage.getItem('mi2_nav_expanded')==='true')
const items=ref<any[]>([]),genres=ref<any[]>([]),behavior=ref<Record<string,any>>({}),busy=ref(false),error=ref(''),notice=ref(''),failures=ref<Record<string,boolean>>({}),pending=ref<Record<string,boolean>>({})
const keyword=ref(''),genre=ref(''),yearFrom=ref(''),yearTo=ref(''),sort=ref('updated'),mode=ref('grid'),state=ref(''),offset=ref(0),hasMore=ref(false),drawer=ref(false),closeButton=ref<HTMLButtonElement>(),filterButton=ref<HTMLButtonElement>()
const draftFrom=ref(''),draftTo=ref(''),draftGenre=ref(''),draftState=ref(''),pageSize=24
const quickGenres=computed(()=>['科幻','剧情','犯罪','悬疑','冒险'].map(name=>genres.value.find(g=>g.name_zh===name)).filter(Boolean))
const visible=computed(()=>items.value.filter(m=>!state.value||behavior.value[String(m.movie_id)]?.[state.value]))
const count=computed(()=>[genre.value,yearFrom.value,yearTo.value,state.value].filter(Boolean).length)
let controller:AbortController|undefined,serial=0
async function api(path:string,signal?:AbortSignal){const r=await fetch('/api/catalog/'+path,{credentials:'same-origin',signal});if(!r.ok)throw new Error(r.status===401?'登录已失效，请重新登录。':r.status===400?'筛选条件无效，请检查年份。':'电影库暂时不可用，请重试。');return (await r.json()).data}
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal,id=++serial;busy.value=true;error.value='';try{
 const p=new URLSearchParams({limit:String(pageSize),offset:String(offset.value),sort:sort.value});for(const [k,v] of Object.entries({keyword:keyword.value.trim(),genre_id:genre.value,year_from:yearFrom.value,year_to:yearTo.value,state:state.value}))if(v)p.set(k,v)
 const [data,g,b]=await Promise.all([api('movies?'+p,signal),api('genres',signal),api('behavior',signal)])
 const rows=data.items
 if(id===serial){items.value=rows;genres.value=g.items;behavior.value=b.state;hasMore.value=data.items.length===pageSize}
 }catch(e){if(!signal.aborted&&id===serial){error.value=(e as Error).message;items.value=[]}}finally{if(id===serial)busy.value=false}}
function sync(){const q=route.query;keyword.value=String(q.q||'');genre.value=String(q.genre||'');yearFrom.value=String(q.year_from||'');yearTo.value=String(q.year_to||'');sort.value=['updated','release','id'].includes(String(q.sort))?String(q.sort):'updated';mode.value=q.view==='list'?'list':'grid';state.value=['favorite','want','watched'].includes(String(q.state))?String(q.state):'';offset.value=Math.max(0,Number(q.offset)||0);if(!route.hash.startsWith('#movie/')&&route.hash!=='#behavior')load()}
watch(()=>route.fullPath,sync,{immediate:true})
function apply(resetPage=true){const query:Record<string,string>={};for(const [k,v] of Object.entries({q:keyword.value.trim(),genre:genre.value,year_from:yearFrom.value,year_to:yearTo.value,sort:sort.value,view:mode.value,state:state.value,offset:resetPage?'0':String(offset.value)}))if(v)query[k]=v;router.push({path:'/movies',query})}
function reset(){keyword.value='';genre.value='';yearFrom.value='';yearTo.value='';state.value='';sort.value='updated';apply()}
function selectGenre(id:string){genre.value=id;apply()}
async function openFilters(){draftFrom.value=yearFrom.value;draftTo.value=yearTo.value;draftGenre.value=genre.value;draftState.value=state.value;drawer.value=true;await nextTick();closeButton.value?.focus()}
function closeFilters(){drawer.value=false;filterButton.value?.focus()}
function filter(){yearFrom.value=draftFrom.value;yearTo.value=draftTo.value;genre.value=draftGenre.value;state.value=draftState.value;closeFilters();apply()}
function focusTrap(e:KeyboardEvent){if(e.key==='Escape'){closeFilters();return}if(e.key!=='Tab')return;const nodes=Array.from((e.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button,input,select'));const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
function posterOf(m:any){return m.poster||movieArtwork[String(m.movie_id)]?.poster||''}
function posterError(e:Event,m:any){const img=e.target as HTMLImageElement;if(m.poster_fallback&&img.getAttribute('src')!==m.poster_fallback){img.src=m.poster_fallback}else{img.style.visibility='hidden'}}
function detail(id:number){sessionStorage.setItem('mi2_library_scroll',String(scrollY));router.push({path:'/movies',query:{...route.query,from:'library'},hash:'#movie/'+id})}
async function act(id:number,kind:string){if(pending.value[id])return;pending.value[id]=true;notice.value='';try{const c=await fetch('/api/v1/auth/csrf',{credentials:'same-origin'});if(!c.ok)throw new Error('登录已失效，请重新登录。');const token=(await c.json()).data.csrf_token;const undo=!!behavior.value[id]?.[kind];const r=await fetch('/api/catalog/behavior',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':token},body:JSON.stringify({event_id:crypto.randomUUID(),movie_id:id,kind,action:undo?'undo':'set',value:null,time:new Date().toISOString(),source:'USER_ACTION'})});if(!r.ok)throw new Error(r.status===409?'行为状态冲突，请到详情页调整。':'保存未确认，请刷新状态后重试。');behavior.value=(await api('behavior')).state;notice.value='已保存';window.dispatchEvent(new Event('mi2-behavior-changed'))}catch(e){notice.value=(e as Error).message}finally{pending.value[id]=false}}
watch(busy,async value=>{if(!value&&!route.hash){await nextTick();const saved=sessionStorage.getItem('mi2_library_scroll');if(saved){window.scrollTo(0,Number(saved));sessionStorage.removeItem('mi2_library_scroll')}}})
const onBehavior=()=>{if(state.value&&!route.hash)load();else api('behavior').then(b=>behavior.value=b.state).catch(()=>{notice.value='个人状态刷新失败，请重试。'})}
window.addEventListener('mi2-behavior-changed',onBehavior)
onBeforeUnmount(()=>{controller?.abort();window.removeEventListener('mi2-behavior-changed',onBehavior)})
</script>
<template>
<MovieDetailView v-if="route.hash.startsWith('#movie/')"/><MyMoviesView v-else-if="route.hash==='#behavior'"/><div v-else class="library-shell" :style="{'--nav-width':expanded?'280px':'52.5px'}"><M9Sidebar @expanded-change="expanded=$event"/><main class="page">
<section class="head"><div><h1>全部电影</h1><p>发现值得停留的故事 · <span class="smallviolet">真实电影目录</span></p></div><div class="viewtoggle" role="group" aria-label="浏览方式"><button :aria-pressed="mode==='grid'" @click="mode='grid';apply(false)">网格</button><button :aria-pressed="mode==='list'" @click="mode='list';apply(false)">列表</button></div></section>
<form class="searchbar" @submit.prevent="apply()"><div class="searchwrap"><svg width="18" height="18" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" fill="none" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/></svg><input v-model="keyword" type="search" placeholder="搜索电影名称" aria-label="搜索电影名称" maxlength="255"/><button>搜索</button></div><div class="tiny-note"><b>发现下一部好电影</b></div></form>
<section class="toolbar" aria-label="电影筛选和排序"><div class="chips" role="group" aria-label="快速类型筛选"><button class="chip" :aria-pressed="!genre" @click="selectGenre('')">全部</button><button v-for="g in quickGenres" :key="g.genre_id" class="chip" :aria-pressed="genre===String(g.genre_id)" @click="selectGenre(String(g.genre_id))">{{g.name_zh}}</button></div><div class="right-tools"><button ref="filterButton" class="filterbtn" :aria-expanded="drawer" @click="openFilters">筛选 <span>{{count}}</span></button><select v-model="sort" class="sortby" aria-label="电影排序" @change="apply()"><option value="updated">最近更新</option><option value="release">上映日期</option><option value="id">目录顺序</option></select><button class="resetbtn" @click="reset">重置</button></div></section>
<div class="context"><span>{{busy?'正在读取电影…':`当前显示 ${visible.length} 部影片`}}</span><span class="right">第 {{offset/pageSize+1}} 页 · 海报进入对应电影详情</span></div>
<div class="active-tags"><span v-if="keyword" class="tag">片名：{{keyword}}</span><span v-if="genre" class="tag">{{genres.find(g=>String(g.genre_id)===genre)?.name_zh}}</span><span v-if="yearFrom||yearTo" class="tag">{{yearFrom||'不限'}} — {{yearTo||'不限'}}</span><span v-if="state" class="tag">本页{{state==='favorite'?'收藏':state==='want'?'想看':'已看'}}</span></div>
<div v-if="busy" class="status" role="status">正在寻找故事…</div><div v-else-if="error" class="status" role="alert"><p>{{error}}</p><button class="filterbtn" @click="load">重试</button></div>
<template v-else><section v-if="visible.length" class="grid" :class="{listmode:mode==='list'}" aria-label="电影海报"><article v-for="m in visible" :key="m.movie_id" class="film"><div class="film-poster"><img v-if="posterOf(m)&&!failures[m.movie_id]" class="poster-art" :src="posterOf(m)" @error="posterError($event,m)" :alt="m.title+'海报'" loading="lazy"/><span v-else class="poster-name">{{m.title}}</span><button class="poster-click" :aria-label="'查看'+m.title+'详情'" @click="detail(m.movie_id)"></button><button class="savebtn" :aria-label="(behavior[m.movie_id]?.favorite?'取消收藏':'收藏')+m.title" :aria-pressed="!!behavior[m.movie_id]?.favorite" :disabled="pending[m.movie_id]" @click="act(m.movie_id,'favorite')"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg></button><div class="poster-actions"><button class="main-action" @click="detail(m.movie_id)">查看详情</button><button :disabled="pending[m.movie_id]" @click="act(m.movie_id,'want')">{{behavior[m.movie_id]?.want?'取消想看':'想看'}}</button></div></div><div class="film-info"><h2 class="film-name"><button @click="detail(m.movie_id)">{{m.title}}</button></h2><div class="film-meta">{{m.release_year||'年份未知'}} · {{m.genres?.map((g:any)=>g.name_zh).join(' / ')||'类型待补充'}}</div><div class="film-source">{{m.ratings?.length?((m.ratings[0].source==='douban'?'豆瓣':m.ratings[0].source.toUpperCase())+' '+m.ratings[0].score_value+' / '+m.ratings[0].score_scale):'暂无来源评分'}}</div><div class="tags-line"><span v-for="kind in ['favorite','want','watched']" v-show="behavior[m.movie_id]?.[kind]" :key="kind" class="behavior">{{kind==='favorite'?'已收藏':kind==='want'?'想看':'已看'}}</span></div><p class="list-desc">{{m.overview||'暂无故事简介。'}}</p><div class="list-actions"><button @click="detail(m.movie_id)">查看详情</button><button :disabled="pending[m.movie_id]" @click="act(m.movie_id,'want')">{{behavior[m.movie_id]?.want?'取消想看':'想看'}}</button></div></div></article></section><div v-else class="empty" style="display:block"><strong>没有找到匹配的电影</strong><span>试试其他片名或调整筛选条件。</span><br/><button @click="reset">清除全部条件</button></div></template>
<nav class="pagination" aria-label="电影库分页"><button :disabled="offset===0||busy" @click="offset-=pageSize;apply(false)">上一页</button><span>{{offset/pageSize+1}}</span><button :disabled="!hasMore||busy" @click="offset+=pageSize;apply(false)">下一页</button></nav>
<p class="notefoot">电影资料来自已授权静态 TMDB 副本。This product uses the TMDB API but is not endorsed or certified by TMDB. <a href="https://www.themoviedb.org/" target="_blank" rel="noopener">TMDB</a></p><p role="status" aria-live="polite">{{notice}}</p>
</main><div v-if="drawer" class="backdrop show" @click.self="closeFilters"><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="filterTitle" @keydown="focusTrap"><div class="drawer-head"><h2 id="filterTitle">筛选电影</h2><button ref="closeButton" class="close" aria-label="关闭筛选" @click="closeFilters">×</button></div><div class="group"><div class="group-title">上映年份</div><label>起始年份<input v-model="draftFrom" type="number" min="1800" max="2199"/></label><label>结束年份<input v-model="draftTo" type="number" min="1800" max="2199"/></label></div><div class="group"><label class="group-title">电影类型<select v-model="draftGenre"><option value="">全部类型</option><option v-for="g in genres" :key="g.genre_id" :value="String(g.genre_id)">{{g.name_zh}}</option></select></label></div><div class="group"><label class="group-title">我的状态（当前结果页）<select v-model="draftState"><option value="">全部</option><option value="favorite">收藏</option><option value="want">想看</option><option value="watched">已看</option></select></label></div><div class="drawer-actions"><button @click="draftFrom='';draftTo='';draftGenre='';draftState=''">重置</button><button class="apply" @click="filter">查看结果</button></div></aside></div></div>
</template>
<style scoped>
.page{padding:24px clamp(20px,2.9vw,50px) 80px;max-width:2000px;margin:0 auto}.head{display:flex;gap:20px;align-items:end;justify-content:space-between;margin:1px 0 19px}.head h1{font-size:26px;line-height:1.2;margin:0 0 10px;font-weight:770;letter-spacing:-.5px}.head p{margin:0;color:#a7a5b7;font-size:12px}.smallviolet{color:#cdbdff}.viewtoggle{display:flex;gap:7px}.viewtoggle button{font-size:12px;padding:10px 15px;border:1px solid var(--border);border-radius:10px;color:#bdbaCA;background:#1a1b26}.viewtoggle button[aria-pressed="true"]{color:#f1eaff;border-color:#9c7acd60;background:#322944}
.searchbar{display:flex;gap:12px;align-items:center;margin-bottom:14px}.searchwrap{display:flex;align-items:center;gap:13px;width:min(650px,100%);height:49px;background:#171823;border:1px solid #ffffff28;border-radius:12px;padding:5px 5px 5px 15px}.searchwrap:focus-within{border-color:#aea0df}.searchwrap svg{flex:none;color:#b6add1}.searchwrap input{border:0;outline:0;min-width:0;flex:1;background:transparent;color:#fff;font-size:13px}.searchwrap input::placeholder{color:#8e8da3}.searchwrap button{height:37px;border:0;border-radius:8px;background:#e6e1f6;color:#27213f;font-weight:770;padding:0 20px;font-size:12px}.searchwrap button:hover{background:#fff}.tiny-note{font-size:11px;color:#87859b}.tiny-note b{color:#c7bcdd;font-weight:600}
.toolbar{border:1px solid var(--border);background:linear-gradient(90deg,#15151fdc,#11121bdc);border-radius:14px;padding:12px 13px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.chips{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.chip{border:1px solid #ffffff1d;border-radius:9px;background:#1d1e2a;color:#c2bfce;padding:9px 13px;font-size:12px}.chip:hover{background:#28293a}.chip[aria-pressed="true"]{background:#3c3155;border-color:#9f8bd680;color:#f6efff}.right-tools{display:flex;gap:10px;align-items:center;margin-left:auto}.filterbtn{background:#2d2540;border:1px solid #826cac8a;color:#eee5ff;border-radius:9px;font-size:12px;padding:10px 13px;white-space:nowrap}.filterbtn span{font-size:11px;color:#c6b3f1;margin-left:5px}.sortby{background:#20212d;border:1px solid #ffffff20;border-radius:9px;color:#e7e4f2;font-size:12px;height:39px;padding:0 12px;min-width:152px}.resetbtn{background:none;border:0;color:#c3aff2;font-size:12px;padding:8px 5px;white-space:nowrap}
.context{display:flex;gap:12px;justify-content:space-between;align-items:center;margin:17px 0 15px;color:var(--muted);font-size:12px;min-height:18px}.context .right{color:#858399;font-size:11px}.active-tags{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 10px}.active-tags:empty{display:none}.tag{border-radius:99px;border:1px solid #8a72bf80;background:#312940;color:#e4d8fc;font-size:11px;padding:5px 10px}.tag button{border:0;background:none;color:#e4d8fc;padding:0 0 0 8px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,220px),1fr));gap:25px 17px;align-items:start}.film{min-width:0}.film-poster{width:100%;aspect-ratio:2/3;border-radius:14px;overflow:hidden;border:1px solid #ffffff28;background:#171927;position:relative;box-shadow:0 5px 17px #0003;transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease;isolation:isolate}.film-poster:hover,.film-poster:focus-within{border-color:#ae9ae57c;transform:translateY(-4px);box-shadow:0 16px 35px #0009}.poster-art{width:100%;height:100%;object-fit:cover}.film-poster:after{content:"";position:absolute;inset:48% 0 0;background:linear-gradient(0deg,#080b18db 0%,#0a0c178a 50%,transparent 100%);pointer-events:none}.poster-name{position:absolute;left:9%;right:8%;bottom:20%;z-index:2;font:800 clamp(18px,2vw,29px) Georgia,serif;line-height:1.02;letter-spacing:.3px;color:white;text-shadow:0 3px 15px #05060ac9;word-break:normal;overflow-wrap:normal}.film[data-film="interstellar"] .poster-name{font-size:clamp(16px,1.45vw,22px)}.film[data-film="shawshank"] .poster-name{font-size:clamp(17px,1.7vw,27px)}.poster-name small{display:block;margin-top:11px;font:600 8px system-ui,sans-serif;letter-spacing:1.8px;color:#e5dff4b8}.marker{position:absolute;z-index:4;top:11px;left:10px;border:1px solid #ffffff42;background:#10131aa8;border-radius:6px;font-size:9px;padding:5px 7px;color:#f3edfa;backdrop-filter:blur(4px)}.marker.demo{color:#ebe5ff;background:#3d305db5}.savebtn{position:absolute;z-index:7;right:10px;top:10px;width:30px;height:30px;display:grid;place-items:center;border-radius:50%;border:1px solid #ffffff50;background:#101421ad;color:#fff;font-size:19px}.savebtn[aria-pressed="true"]{color:#e1a1ce;background:#6a325e;border-color:#d4a2d1}.poster-actions{z-index:5;position:absolute;bottom:11px;left:10px;right:10px;display:flex;gap:7px;opacity:0;transform:translateY(6px);transition:opacity .2s,transform .2s}.film-poster:hover .poster-actions,.film-poster:focus-within .poster-actions{opacity:1;transform:none}.poster-actions button{flex:1;min-width:0;border:1px solid #aca8c055;border-radius:8px;background:#141627de;padding:9px 5px;color:#f2edf9;font-size:11px;font-weight:640;backdrop-filter:blur(8px)}.poster-actions .main-action{background:#e5e0f2;color:#1f1b2c;border-color:transparent}.poster-click{position:absolute;inset:0;border:0;background:transparent;z-index:3;width:100%;height:100%;cursor:pointer}.poster-click:focus-visible{outline:3px solid #dbcaff;outline-offset:-5px}.poster-actions button:hover{filter:brightness(1.15)}.film-info{padding:12px 3px 0}.film-name{font-size:15px;font-weight:750;line-height:1.4;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.film-meta{color:#aaa8b7;font-size:11px;line-height:1.6;margin-top:5px}.film-source{color:#ad9bc7;font-size:10px;margin-top:8px}.film-source.demo{color:#858199}.list-desc{display:none;color:#a9a7b7;font-size:12px;line-height:1.75;margin-top:9px}.list-actions{display:none;gap:8px;margin-top:15px}.list-actions button{border-radius:9px;border:1px solid #ffffff27;background:#232434;color:#f2eafa;padding:9px 13px}.list-actions button:first-child{background:#e6e0f3;color:#241f2d}.tags-line{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.behavior{font-size:10px;color:#e0b5db;border-radius:99px;background:#b45faf18;padding:3px 7px}
.grid.listmode{display:flex;flex-direction:column;gap:13px}.listmode .film{display:flex;align-items:stretch;width:100%;gap:18px;padding:12px;border:1px solid var(--border);border-radius:13px;background:#13141e}.listmode .film-poster{width:118px;flex:none}.listmode .film-info{flex:1;min-width:0;padding:3px 0}.listmode .film-name{font-size:18px}.listmode .list-desc{display:block}.listmode .list-actions{display:flex}.listmode .poster-name{font-size:12px}.listmode .poster-name small{display:none}.listmode .poster-actions{display:none}.listmode .film-poster:hover{transform:none}
.empty{display:none;padding:72px 24px;text-align:center;border:1px dashed #61597275;border-radius:18px;color:#bbb6cb}.empty strong{font-size:18px;display:block;margin-bottom:9px;color:#efe8fb}.empty button{padding:10px 14px;color:#efe8ff;border:1px solid #7e6aad;background:#342c45;border-radius:9px;margin-top:15px}.notefoot{margin:39px 0 0;color:#777386;font-size:11px;line-height:1.8;border-top:1px solid #ffffff10;padding-top:17px}.notefoot strong{color:#b2a7c4}
.backdrop{display:none;position:fixed;inset:0;background:#03030acc;z-index:60;backdrop-filter:blur(5px)}.backdrop.show{display:block}.drawer{position:absolute;right:0;top:0;bottom:0;width:min(400px,95vw);overflow-y:auto;background:#171722;border-left:1px solid #ffffff18;box-shadow:-16px 0 48px #0008;padding:26px}.drawer-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:28px}.drawer-head h2{margin:0;font-size:20px}.close{width:37px;height:37px;border-radius:50%;background:#ffffff12;color:#ede6fb;border:1px solid #ffffff26;font-size:21px}.group{margin:0 0 25px}.group-title{color:#d8d4e3;font-size:13px;font-weight:750;margin-bottom:13px}.options{display:flex;flex-wrap:wrap;gap:8px}.options button{background:#232434;border:1px solid #ffffff1b;border-radius:9px;color:#beb9d1;padding:10px 12px;font-size:12px}.options button[aria-pressed="true"]{border-color:#a48cdf;background:#403357;color:#fff}.drawer-actions{display:flex;gap:10px;border-top:1px solid #ffffff18;padding-top:18px}.drawer-actions button{flex:1;border-radius:10px;padding:12px;border:1px solid #ffffff2a;background:#292a38;color:#e7e1f5}.drawer-actions .apply{background:#e6e0f3;color:#252035}

:global(body:has(.library-shell)){margin:0;background:#080a13;color:#f2eff9}.library-shell{--border:rgba(185,165,221,.13);--muted:#aaa4bc;--violet:#c2b2fb;position:relative;z-index:1;min-height:100vh;background:#080a13;color:#f2eff9;font-family:Inter,"Microsoft YaHei",sans-serif}.library-shell *{box-sizing:border-box}.library-shell button,.library-shell input,.library-shell select{font:inherit}.library-shell button{cursor:pointer}.library-shell button:disabled{opacity:.5;cursor:default}.library-shell a{color:inherit}.library-shell :focus-visible{outline:2px solid #c2a6f4;outline-offset:3px}.page{margin-left:var(--nav-width);transition:margin-left .25s ease;max-width:none;padding-top:24px;min-height:100vh}.grid{grid-template-columns:repeat(6,minmax(0,1fr));gap:22px 13px}.film-name{margin:0}.film-name button{border:0;background:none;color:inherit;padding:0;font-weight:750;font-size:inherit;text-align:left;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.film-source{min-height:14px}.tags-line:empty{display:none}.list-desc{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.grid:not(.listmode) .list-desc{display:none}.poster-art{display:block}.film-info{min-width:0}.pagination{display:flex;justify-content:center;align-items:center;gap:20px;margin:35px 0}.pagination button{border:1px solid var(--border);background:#20212d;color:#e7e4f2;border-radius:9px;padding:10px 18px}.status{padding:70px 20px;text-align:center;color:#c2bdcb}.drawer label{display:flex;flex-direction:column;gap:10px;margin:12px 0;font-size:13px}.drawer input,.drawer select{width:100%;background:#232434;color:#f2eff9;border:1px solid var(--border);border-radius:9px;padding:11px}.notefoot a{text-decoration:underline}.listmode .list-desc{display:-webkit-box}.listmode .film-poster{aspect-ratio:2/3;align-self:start}.listmode .film-poster:after{display:none}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;scroll-behavior:auto!important}}

